 WHERE `entite` = 'brands' AND `entite_id` = 'Epic Cigars' AND `champ` = 'history' AND `lang` = 'de' AND `source_hash` = '1702f0224afbf9344d45369efb7559f28b6af056';
-- brands|Espinosa|history|de — à la sortie = Auslieferung
UPDATE `brands` SET `history_de` = 'Erik Espinosa hatte bereits zwei Marken bekannt gemacht — 601 und Murcielago — unter einer Firma, die er zu zweit führte, ehe er allein den Namen übernahm, der der seine ist. Dann tat er, was wenige Markengründer tun: seine eigene Manufaktur eröffnen, La Zona in Estelí, statt weiter anderswo rollen zu lassen.

Dieser Schritt von der Marke zum Hersteller verändert alles. Das Haus kontrolliert seine Blends nun vom Rollen bis zur Auslieferung, produziert für sich selbst ebenso wie für andere Marken und kann sich kurze Serien leisten, die kein Auftragsfertiger annehmen würde.

Der Stil ist nicaraguanisch ohne Umschweife: kräftig, pfeffrig, mit einer offenen Substanz, die keine kubanische Finesse sucht. Laranja Reserva, um ein brasilianisches Deckblatt herum gebaut, ist sein bekanntester Ausdruck und einer der seltenen brasilianischen Erfolge außerhalb Brasiliens.

La Zona hat sich unterdessen als eigenständige Manufaktur einen Namen gemacht: Mehrere Boutique-Marken lassen dort rollen, was die beste Empfehlung ist, die eine Werkstatt erhalten kann.'
 WHERE `name` = 'Espinosa' AND SHA1(TRIM(`history`)) = 'b8c9006f41a59b5497411889a49e8dae3b9a6855';
