 WHERE `entite` = 'brands' AND `entite_id` = 'Xhaxhi Bobi' AND `champ` = 'history' AND `lang` = 'de' AND `source_hash` = '7625e38a41de8de1749e09f214ae281e1df1b6af';
-- brands|Zigarren Manufaktur Dresden|history|de — Unternehmermagazin statt Gründermagazin
UPDATE `brands` SET `history_de` = 'Die Zigarren Manufaktur Dresden ist der Traum eines Kubaners: Lázaro Javier Herrera Cabrera, Torcedor in dritter Generation und Tabakgütekontrolleur in seinem Land, wollte seine eigene Manufaktur und eröffnete sie 2015 in Sachsen, in Dresden, mit einem Gründerteam, zu dem Katrin Lieberum gehört. Das Konzept war 2013 geschrieben worden; das zur Eröffnung veröffentlichte Gründerporträt erzählt den Rest — Förderungen, die Tabak ausschließen, eine kubanische Staatsangehörigkeit, die Kredite erschwert, und die Entscheidung, es trotzdem zu tun.

Die Werkstatt rollt Longfiller vollständig von Hand, wie auf Kuba: Einlage aus ganzen Blättern, Zedernformen, ein Deckblatt, das der Torcedor vor den Augen der Besucher aufbringt, die ihm bei der Arbeit zusehen können. Die Tabake sind importiert; sächsisch ist die Handbewegung. Dieser Atlas ordnet das Haus daher in Deutschland ein, das er hier als Rollort öffnet — eine Premiere für ein Land, das man vor allem durch seine Maschinenzigarren kennt.

Es ist ein kleines Haus, ohne Fachpresse im englischsprachigen Sinn; seine Quelle ist ein Dresdner Unternehmermagazin. Der Eintrag hält sich an das, was es sagt.'
 WHERE `name` = 'Zigarren Manufaktur Dresden' AND SHA1(TRIM(`history`)) = 'd616f19e43a9073176b0e1aa9eda066606556545';
