UPDATE `brands` SET `gamme_de` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"Die breiteste Linie, ihre Vitolas nach musikalischem Vokabular benannt — Nodal ist ausgebildeter Musiker. Von Grund auf quadratisches Format, was selten ist.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"Die kurzen Serien des Hauses, mit einem Code statt eines Namens bezeichnet. Diese Linie hat die Marke bekannt gemacht.","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"Auf Tabaken von 1999 und 2001 aufgebaut, die aus dem Cibao-Tal zurückgehalten wurden. Der Name bezeichnet das Reifefach — die ganze Marke steckt in diesem Gedanken.","vitolas":["Bin No. 1"],"wrapper":"Dominikanisch"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"Benannt nach einer alten kubanischen Sorte, schwer anzubauen und deshalb lange aufgegeben. 2016 herausgebracht, bei A.J. Fernandez in Nicaragua gerollt: Deckblatt kubanischer Saat aus Nicaragua, Umblatt aus Nicaragua, Einlage Pelo de Oro aus Nicaragua.","vitolas":["Rondo","Mezzo"],"wrapper":"Kubanische Saat aus Nicaragua"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","story":"2014 bei Boutique Blends auf den Markt gebracht und damals in der Tabacalera Palma gerollt, kehrt sie im Januar 2025 unter dem Namen Aging Room La Bohème zurück, mit einer neuen Mischung von A.J. Fernandez in Nicaragua, im Dezember 2024 als mittel bis kräftig vorgestellt. Hybrides Deckblatt aus Broadleaf- und Habano-Saatgut, angebaut im Connecticut-Tal, nicaraguanisches Umblatt und nicaraguanische Einlage: vier Formate, benannt nach Puccinis Oper, Mimi (3 1/2 x 46), Pittore (5 1/8 x 52), Poeta (5 3/4 x 54) und Musico (6 1/4 x 60).","vitolas":[],"wrapper":"Connecticut-Hybrid"}]'
