UPDATE `brands` SET `gamme_de` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"Am 18. November 1995 in den Verkauf gebracht und von arturofuente.com als die erste dominikanische Puro-Zigarre vorgestellt, Deckblatt eingeschlossen. Das Deckblatt wächst auf dem Château de la Fuente bei Bonao. Formate der Liste des Hauses: Robusto 5¼ x 50, Double Corona 7⅝ x 49, Reserva D''Chateau 7 x 48, PerfecXion X 6¼ x 48, PerfecXion No.2 6⅜ x 52, Fuente Fuente 5⅝ x 46. In begrenzten Mengen an eine Handvoll Einzelhändler geliefert, schreibt Tobacconist of Greenwich im Juli 2025.","vitolas":["Robusto","Double Corona","Reserva D''Chateau","PerfecXion X","PerfecXion No.2","Fuente Fuente"],"wrapper":"Château de la Fuente (DR)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"Trägt den Namen von Carlos Fuente Sr., so arturofuente.com; die Seite beschreibt seltene, bis zu zehn Jahre gereifte Tabake unter einem Kamerun-Deckblatt. Laut Carlos Fuente Jr. wurde die erste verkaufte Don Carlos, 1976, in Estelí in Nicaragua gerollt (Juni 2026). Formate der Liste des Hauses: Robusto 5 x 50, Double Robusto 5¾ x 52, Belicoso 5⅜ x 52, The Man 5¼ x 50, Presidente 6½ x 50, Personal Reserve Eye of the Shark 5¼ x 52.","vitolas":["Robusto","Double Robusto","Belicoso","The Man","Presidente","Personal Reserve Eye of the Shark"],"wrapper":"Kamerun"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"1981 lanciert, laut arturofuente.com, ein Jahr nach der Eröffnung von Fuente Ltd; die Seite stellt ihre Figurado-Form als damalige Premiere für die Branche dar. Bespoke Unit berichtet, dass Carlos Fuente Sr. alte Formen für Perfectos in einem Lagerhaus in Florida wiederfand, und datiert die Mischung von Carlito auf 1983, als Hommage an den amerikanischen Schriftsteller. Kamerun-Deckblatt über dominikanischem Umblatt und dominikanischer Einlage, laut dieser Seite mild bis mittelkräftig (2017, 2023 aktualisiert). Die Masterpiece, 9 x 52, ist das längste Format der Liste des Hauses.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Kamerun"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Eingeführt 2000 mit fünf Formaten, laut Cigar Coop (August 2014); die No.77 Shark folgt um 2002. Cigar Coop bringt sie mit dem Hurrikan Georges von 1998 in Verbindung: Carlos Fuente Jr. soll, aus Sorge, das Deckblatt für die OpusX könnte knapp werden, die Mischung der OpusX mit einem Connecticut Broadleaf umhüllt haben. Das Haus schreibt, dass die Maduro-Deckblätter in Cognacfässern gereift werden, und stellt die Shark (5⅞ x 48/64) als den ersten Torpedo vor, der von einem gerundeten Parejo zu einer eckigen Pressung übergeht.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"story":"Ende 2013 in begrenzter Zuteilung an Einzelhändler auf den Markt gebracht, sagt Cigar Coop, und von arturofuente.com als letzte Mischung des verstorbenen Carlos Fuente Sr. vorgestellt, gedacht als Erinnerung an die Zigarren, die er in jungen Jahren mit seinem Vater drehte und rauchte, mit kubanischem Tabak. Deckblatt Havana aus Ecuador über Umblatt und longfiller, beide dominikanisch und aus kubanischer Saat, gerollt in der Tabacalera A. Fuente y Cia. Die Formate tragen die Namen kubanischer Dominosteine: Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 und Divine Inspiration 6⅛ x 47. Stärke von Cigar Coop 2014 als medium beschrieben, im letzten Drittel auf medium-full ansteigend, und von einem Einzelhändler im Oktober 2026 als medium-full.","vitolas":[],"wrapper":"Havana aus Ecuador"},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","story":"Edition von OpusX, deren Tabak, vollständig dominikanisch, im Sommer 2004 auf dem Château de la Fuente für die Dreharbeiten zum Film The Lost City (erschienen 2005, Regie: Andy Garcia) gepflanzt wurde und danach fünf Jahre gereift ist, laut fuenteagedselection.com, die sie als medium bis kräftig bezeichnet. Gerollt in der Tabacalera A. Fuente; eine Meldung vom Juni 2024 ordnet sie der jährlichen Zuteilung Aged Selection zu, die an Einzelhändler geliefert wird. Formate: Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 und Carlito''s A 9¼ x 47.","vitolas":[],"wrapper":"Dominikanische Republik"}]'
