UPDATE `brands` SET `gamme_de` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"Die Gründungsserie. Deckblatt Connecticut Shade über einer dominikanischen Mischung, von Fuente gerollt. Sahne, Vanille, geröstetes Getreide. Gleichmäßig, elegant, ohne Überraschungen. Das Magnum (52 x 127 mm) wird am häufigsten verlangt. Die Ashton Classic ist die Zigarre, die man anbietet, wenn man den Geschmack seines Gastes nicht kennt.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"1999 lanciert — der andere Ashton. Ecuadorianisches Sun-Grown-Deckblatt über einer nicaraguanisch-dominikanischen Mischung. Kräftig: schwarzer Kaffee, Schokolade, Cayennepfeffer. Die VSG zeigt ein Haus, das Kraft aufbringen kann, wenn es das will.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"Die Prestige-Serie — nach dem Rollen weitere zwölf bis vierundzwanzig Monate in Kisten aus spanischer Zeder gereift. Deckblatt Connecticut Shade. Verfeinerte Haselnuss, Berghonig, weiße Zeder. Komplex, ohne fordernd zu sein: genau das will sie sein.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Ecuador, je nach Linie","vitolas":[],"story":"Nicaraguanische Linie, 2007 mit José „Pepin“ Garcia auf den Markt gebracht, gefertigt von der Familie Garcia in der Fabrik My Father in Estelí. Quintessence, Deckblatt Habano Rosado aus Ecuador über nicaraguanischem longfiller, wird von Ashton Distributors als medium-full bezeichnet, in sechs Formaten; Golden Hour, im April 2026 Einzelhändlern angekündigt und auf der PCA gezeigt, ergänzt sechs Formate mit Deckblatt Habano aus Ecuador, über nicaraguanischem Umblatt und einer Einlage von den Garcia-Farmen, laut Cigar Coop."}]'
