UPDATE `brands` SET `gamme_de` = '[{"name":"Cohiba Blue","color":"#1A3A6B","story":"Im April 2017 eingeführt: Deckblatt und Umblatt aus Honduras (Olancho San Agustín), Einlage aus Honduras (Jamastrán), Nicaragua (Ometepe) und der Dominikanischen Republik (Piloto Cubano), gerollt bei General Cigar Dominicana in Santiago. Das Haus beschreibt sie 2026 mit der Formel „Luxus ohne Getue“.","wrapper":"Honduras (OSA)"},{"name":"Cohiba Red Dot","color":"#8B0000","story":"Deckblatt aus Kamerun auf indonesischem Umblatt (Jember) und dominikanischer Einlage, in der Dominikanischen Republik von General Cigar gerollt, laut dem Einzelhändler Corona Cigar Co. Das Haus beschreibt sie 2026 mit der Formel „A modern classic“.","wrapper":"Kamerun"},{"name":"Cohiba Macassar","color":"#2C1A0E","story":"Auf der IPCPR 2016 vorgestellt: Connecticut-Deckblatt aus Havanna-Saatgut, sechs Jahre gealtertes Broadleaf-Umblatt aus Connecticut, Einlage aus der Dominikanischen Republik (Mao) und Nicaragua (Jalapa); die Tabake reifen mindestens vier Jahre, das letzte im Rumfass, schreibt Cigar Coop. Ihre Mischung leitet sich von der des Comador ab, den die Macassar ersetzt.","wrapper":"Connecticut (Havanna-Saatgut)"},{"name":"Cohiba Nicaragua","color":"#3D5C1A","story":"Auf der IPCPR 2014 als erste in Nicaragua hergestellte Cohiba vorgestellt, bei STG Estelí: Deckblatt aus Honduras (sonnengewachsenes Blatt Colorado oscuro), Umblatt aus Jalapa, Einlage aus Estelí (und laut Cigar Coop aus Jalapa).","wrapper":"Honduras (Colorado oscuro)"},{"name":"Cohiba Riviera","color":"#0F6B6B","force":null,"wrapper":"Mexiko (San Andrés)","vitolas":[],"story":"2023 eingeführt, die erste kastengepresste Cohiba und die erste mit Deckblatt San Andrés (Mexiko): in Honduras angebautes Connecticut-Umblatt, Einlage aus Honduras (Jamastrán, La Entrada) und Nicaragua (Condega, Estelí), gerollt bei STG Estelí. Auf der PCA 2024 kam ein Lancero (7 x 38) hinzu."}]'
