UPDATE `brands` SET `gamme_de` = '[{"name":"Serie L","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Ursprüngliche Mischung, cremig und erdig, so das Haus; Deckblatt Habano aus Ecuador, Umblatt aus Jalapa, Einlage aus Jalapa und Estelí, mittlere Stärke laut Cigar World, in Robusto (5 x 50), Toro (6 x 54) und Churchill (7 x 50), so der Artikel vom März 2024."},{"name":"Serie O","color":"#4A2C1A","force":"Full","wrapper":"San Andrés oscuro (Mexiko)","vitolas":[],"story":"Mexikanisches Deckblatt San Andrés negro oscuro, dominikanisches Umblatt, Einlage aus Condega, seco und ligero, und aus Jalapa, viso, volle Stärke, so das Haus, in Corona (5 1/2 x 46), Robusto (5 x 50), Toro (6 x 54), 6 x 60 box-pressed und Giggly Piggly (4 x 60 mit pigtail), in Kisten zu 13 Stück, so Cigar Coop."},{"name":"Skinny Bastarda","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Corona von 5 1/4 x 42 in Päckchen zu fünf Stück, mit geheim gehaltener Mischung, von Raquel und Patricia Quesada geschaffen und in der Fabrik Quesada in der Dominikanischen Republik gerollt, so Stogiepress; das Haus sagt, sie werde von Frauen für Frauen gemacht."},{"name":"Wingman","color":"#A0522D","force":null,"wrapper":"Habano (Ecuador)","vitolas":[],"story":"Erste limitierte Edition, am 6. November 2025 angekündigt, Toro 6 x 52, Deckblatt Habano aus Ecuador über einem Umblatt Sumatra aus Indonesien und einer Einlage aus nicaraguanischen Tabaken; das Haus sagt nicht, wer sie rollt, schreibt Cigar Coop."},{"name":"Department of Honor","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Limitierte Edition, den Ersthelfern und den sechs Teilstreitkräften der Vereinigten Staaten gewidmet: vier Coronas, zwei je Mischung, die eine, mit Deckblatt Habano, leichter als die andere, mit Deckblatt San Andrés, in 400 Päckchen, den Einzelhändlern der PCA 2026 vorbehalten und ab Mitte Mai 2026 versandt; in Nicaragua gefertigt, Fabrik nicht genannt, so die Premium Cigar Association."}]'
