UPDATE `brands` SET `gamme_de` = '[{"name":"No.9","color":"#1C0A00","force":"Full","story":"Die ursprüngliche Mischung der Marke. Deckblatt Connecticut River Valley Broadleaf No. 1 Dark, Umblatt Mata Fina aus Brasilien, Einlage aus Honduras und Nicaragua, sagt das Haus. Formate im Katalog des Hauses: Coronets, Robusto, Corona Viva, Toro (6 x 52 Zoll), Belicoso, Corona Doble sowie die Flying Pig als saisonale Ausgabe.","vitolas":["Toro","Robusto","No.9 Perfecto","Flying Pig","Little Bigger Fish","Petit Lancero"],"wrapper":"Connecticut Broadleaf"},{"name":"T52","color":"#2D0A00","force":"Full","story":"Deckblatt Habano aus Connecticut, am Stängel geschnitten und getrocknet, laut Haus 30 bis 36 Monate gereift; Umblatt Mata Fina, Einlage aus Honduras und Nicaragua. Dieselben Formate wie die No.9 im Katalog des Hauses. Laut Cigar Coop 2009 erschienen.","vitolas":["Toro","Flying Pig","Petit Toro","Unico Serie"],"wrapper":"Connecticut Habano (stalk-cut)"},{"name":"Unico Serie","color":"#3D1C00","force":"Full","story":"Serie, laut Cigar Coop 2010 eingeführt: eine einzigartige Mischung je Format, Ableger der No.9 und der T52. Die Papas Fritas, eine kurze Corona von 115 x 44 mm (4 1/2 x 44 Zoll), haben eine Kurzeinlage aus den Resten der übrigen Liga Privada unter einem Deckblatt Connecticut Broadleaf Maduro; das Haus bietet sie heute als eigene Kollektion an.","vitolas":["Papas Fritas","Unico Serie jährlich"],"wrapper":"Je nach Ausgabe"}]'
