UPDATE `brands` SET `gamme_de` = '[{"name":"Reserve","color":"#4A2C1A","force":"Medium-Full","wrapper":"Geschwärztes Connecticut Broadleaf","vitolas":[],"story":"Geschwärztes Deckblatt Connecticut Broadleaf über einem nicaraguanischen Umblatt und einer dominikanischen, nicaraguanischen und peruanischen Einlage, mittlere bis volle Stärke, so das Haus, in fünf Vitolas: Robusto (5 x 50), Toro (6 x 50), Churchill (7 x 50), No. 2 Belicoso (6 1/8 x 52) und Torbusto (5 1/2 x 60)."},{"name":"Bold Nicaragua","color":"#4A3728","force":"Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Dunkles Deckblatt San Andrés über einem nicaraguanischen Umblatt, mit nicaraguanischer und dominikanischer Einlage, so das Haus, das von nicaraguanischen Tabaken spricht, die mehr als vier Jahre gereift sind; in drei Vitolas, Robusto (5 x 50), Toro (6 x 54) und Magnum (6 x 60); volle Stärke, so Payless Cigars and Pipes."},{"name":"Vintage Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano (Nicaragua, 2019)","vitolas":[],"story":"Deckblatt, Umblatt und Einlage aus Nicaragua, so das Haus, das angibt, die Linie werde bei A.J. Fernandez gefertigt; Deckblatt Habano aus der Ernte 2019, so Cigar Coop; in drei Vitolas, Robusto (5 x 50), Toro (6 x 54) und Magnum (6 x 60), in Kisten zu zwanzig Stück; mittlere bis volle Stärke, so Cigars Direct."}]'
