UPDATE `brands` SET `gamme_de` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"Die Zigarre, in ein ganzes Tabakblatt gewickelt, das vor dem Anzünden abgenommen wird. Sie hat das Haus bekannt gemacht und macht es von weitem erkennbar.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"Corojo, Connecticut, Maduro oder Sumatra je nach Fassung"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"Das Gründungsjahr als Name. Die klassische Linie des Hauses, ohne Blatthülle — jene, an der man den Tabak beurteilt und nicht die Idee.","vitolas":["Robusto","Toro"],"wrapper":"Honduranische Mischung"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"Die kräftige Seite, in kurzen Serien. Das Haus arbeitet viel mit Händlern zusammen, und dieses Register eignet sich dafür.","vitolas":["Robusto","Toro"],"wrapper":"Honduranische Mischung"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés aus Jalapa","vitolas":[],"story":"Linie, die den Namen von Jim Robinson trägt, einem Einzelhändler aus Pittsburgh, auf der IPCPR 2014 im Format No. 2 mit ausgefranstem Fuß vorgestellt; im Mai 2025 gehören ihre Zigarren zum Portfolio des Hauses. Im Oktober 2026 beschreibt ein Online-Einzelhändler ein Deckblatt San Andrés aus Jalapa mit Connecticut-Band und Oscuro-Spitze über nicaraguanischen Longfillern, von mittlerer Stärke; der Barber Pole von 2025, im Format 6 x 52, verflechtet Deckblätter Connecticut und Corojo."}]'
