-- brands|Padrón|gamme|de — Natur zu Natural, einheitlich
UPDATE `brands` SET `gamme_de` = '[{"name":"1964 Anniversary Series","color":"#8B0000","force":"Medium-Full","story":"1994 zum dreißigjährigen Bestehen des Hauses eingeführt, sagt padron.com, zunächst in der Kiste gepresst, nach kubanischer Tradition. Sonnengewachsenes Deckblatt, Natural oder Maduro, und vier Jahre gereifter Tabak. Sechzehn Formate (Länge in Zoll x Ringmaß), darunter das Exclusivo 5½ x 50, das Monarca 6½ x 46, das Torpedo 6 x 52, das Presidente 6 x 50 und das Diplomatico 7 x 50.","vitolas":["Exclusivo","Monarca","Torpedo","Presidente","Diplomatico"],"wrapper":"Sonnengewachsen, Natural/Maduro"},{"name":"Serie 1926","color":"#722F37","force":"Full","story":"2002 zum fünfundsiebzigsten Geburtstag von José O. Padrón erschienen, sagt padron.com; ein 2014 veröffentlichtes Porträt datiert sie auf 2001, das Jahr, in dem er 75 wurde (er wurde im Juni 1926 geboren). Die Serie trägt das Geburtsjahr von José Orlando, schreibt Holt''s. Fünf Jahre gereifter Tabak, sonnengewachsenes Deckblatt, Natural oder Maduro, zehn Formate: No.1 (6¾ x 54, Länge in Zoll x Ringmaß), No.2, No.6, No.9, No.35, No.40, No.47, No.48, No.80 und No.90.","vitolas":["No.1","No.2","No.6","No.9","No.35","No.40","No.47","No.48","No.80","No.90"],"wrapper":"Sonnengewachsen, Natural/Maduro"},{"name":"Padrón Series","color":"#A0522D","force":"Medium-Full","story":"Die Padrón Series, sagt padron.com: fünfzehn Langfüller-Formate, als mittelkräftig bis kräftig beschrieben, vom Cortico bis zum Magnum, aus sonnengewachsenem Tabak, der mindestens zweieinhalb Jahre gereift ist. Dazu gehören die 2000 (5 x 50), 3000 (5½ x 52), 4000 (6½ x 54), 5000 (5½ x 56) und 7000 (6¼ x 60).","vitolas":["2000","3000","4000","5000","6000","7000"],"wrapper":"Sonnengewachsen"},{"name":"Dámaso","color":"#C04000","force":"Mild-Medium","story":"Auf der IPCPR im Juli 2015 vorgestellt, laut Cigar Coop: der erste Connecticut von Padrón, rund gerollt und nicht gepresst, mit nicaraguanischem Umblatt und nicaraguanischer Einlage. Das Haus gibt sie mit Connecticut-Deckblatt aus Ecuador an, im Profil mild bis mittelkräftig, und benennt die Linie nach Dámaso Padrón, dem ersten Padrón, der Ende des 19. Jahrhunderts von den Kanaren nach Kuba kam; Cigar Coop macht ihn zum Großvater von José O. Padrón. Formate: No.8 (5½ x 46), No.12 (5 x 50), No.15 (6 x 52), No.17 (7 x 54) und zwei kräftigere Red Label, die No.32 und No.34.","vitolas":["No.8","No.12","No.15","No.17","No.32","No.34"],"wrapper":"Connecticut aus Ecuador"}]'
