UPDATE `brands` SET `gamme_de` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"Einzige Vitola der Marke zu Beginn, laut habanos.com, wo sie mit Ringmaß 40 und 192 mm Länge angegeben wird (Pressemitteilung vom 7. Oktober 2003); sie bleibt danach im Programm, in klarlackierten Kisten zu 12 und 24 und in Päckchen zu 5. Die Fachpresse führt sie mit 7 1/2 Zoll x 40 (2019). Habanos stuft die Marke in mittlerer Stärke ein.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"Vitola mit Ringmaß 40 x 110 mm, am 10. November 2003 in London zusammen mit den Coloniales und den Robustos Extra vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 5, sagt habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"Vitola mit Ringmaß 44 x 132 mm, 2003 zugleich mit den Reyes und den Robustos Extra vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 5, sagt habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"Vitola mit Ringmaß 50 x 155 mm, 2003 vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 3, sagt habanos.com, dessen Markenseite außerdem die Robustos T auf 2009 datiert (ohne ihre Maße anzugeben; Wikipedia führt sie mit 4 7/8 Zoll x 50 auf). Die Robustos Extra, zuvor laut Fachpresse eingestellt, kehrten im Februar 2024 zum 55-jährigen Bestehen der Marke in die reguläre Produktion zurück (6 1/8 Zoll x cepo 50, Kisten zu 12 und zu 3, neue Aufmachung). Der aktuelle Status der Robustos T ist durch keine gelesene Seite belegt.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda und Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: Vitola de galera Torres, Ringmaß 54 (21,43 mm) x 110 mm, im April 2014 vorgestellt. Topes: Ringmaß 56 (22,23 mm) x 125 mm, Edición Limitada 2016, dann 2019 reguläre Reihe. Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm): 2019. Alle laut habanos.com, das die Marke in mittlerer Stärke angibt.","vitolas":[],"wrapper":"Vuelta Abajo"}]'
