UPDATE `feuilles` SET `genese_de` = 'La Palma baut seit dem 18. Jahrhundert Tabak an, für den Handel mit Amerika. Doch erst im 19. Jahrhundert gewann das Blatt seinen Charakter: Der Zusammenbruch der Cochenille ruinierte die Insel, und Palmeros, die ihr Glück auf Kuba gesucht hatten, brachten die ersten kubanischen Samen mit — samt der dort erlernten Handgriffe.'
